content.rust:
#[derive(Debug, Clone, Copy, PartialEq)]
pub enum NucleusState {
    Actif,
    Latent,
    Instable,
}

#[derive(Debug, Clone)]
pub struct Nucleus {
    pub etat:      NucleusState,
    pub gravite:   f64,   // -2.0 .. +3.0
    pub pulsation: f64,   // 20.0 .. 120.0 bpm
}

impl Default for Nucleus {
    fn default() -> Self {
        Self { etat: NucleusState::Actif, gravite: {{gravite}}, pulsation: {{pulsation}} }
    }
}
